import{_ as l,o as t,c as a,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"CephFS Tell-Me-What-Happened --Yes-I-Really-Really-Mean-It - Anthony DAtri, IBM","description":"","frontmatter":{"title":"CephFS Tell-Me-What-Happened --Yes-I-Really-Really-Mean-It - Anthony DAtri, IBM","date":"2025-11-19T00:00:00.000Z","updated":"2025-11-20T00:00:00.000Z","tags":["CephFS","审计日志","Ceph存储","分布式文件系统","Ceph社区"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/CephFS_Tell-Me-What-Happened_--Yes-I-Really-Really-Mean-It_-_Anthony_D_Atri_IBM.md","filePath":"posts/2025/CephFS_Tell-Me-What-Happened_--Yes-I-Really-Really-Mean-It_-_Anthony_D_Atri_IBM.md","lastUpdated":1780459816000}'),r={name:"posts/2025/CephFS_Tell-Me-What-Happened_--Yes-I-Really-Really-Mean-It_-_Anthony_D_Atri_IBM.md"};function n(i,e,s,p,h,d){return t(),a("div",null,[...e[0]||(e[0]=[o('<h3 id="cephfs-审计日志需求讨论会议纪要" tabindex="-1"><strong>CephFS 审计日志需求讨论会议纪要</strong> <a class="header-anchor" href="#cephfs-审计日志需求讨论会议纪要" aria-label="Permalink to &quot;**CephFS 审计日志需求讨论会议纪要**&quot;">​</a></h3><h4 id="会议基本信息" tabindex="-1"><strong>会议基本信息</strong> <a class="header-anchor" href="#会议基本信息" aria-label="Permalink to &quot;**会议基本信息**&quot;">​</a></h4><ul><li><strong>主持人</strong>: Anthony Dri（IBM Ceph 支持团队成员，Ceph Ambassador）</li><li><strong>缺席人员</strong>: Daria、Veni Shanker（IBM Ceph 团队成员，原定主讲人）</li><li><strong>会议主题</strong>: Ceph 文件系统（CephFS）审计日志的需求与开发进展</li></ul><h4 id="主要讨论内容" tabindex="-1"><strong>主要讨论内容</strong> <a class="header-anchor" href="#主要讨论内容" aria-label="Permalink to &quot;**主要讨论内容**&quot;">​</a></h4><ol><li><p><strong>CephFS 调试挑战</strong></p><ul><li>CephFS 调试面临困难，包括复杂的状态变更和操作追溯困难。</li><li>命令执行顺序和完成状态对故障排查至关重要。</li></ul></li><li><p><strong>现有问题诊断流程</strong></p><ul><li>通过 Ceph 用户邮件列表提交问题，但信息可能不完整。</li><li>需要关键数据，如命令列表、MDS 状态、MDS map 历史、文件系统恢复记录和 Perf dump 数据。</li></ul></li><li><p><strong>CephFS 审计日志方案（Audit Log）</strong></p><ul><li>记录所有命令的时序执行历史，包含命令、时间、状态和返回值。</li><li>基于 SQLite 数据库，存储于 <code>.audit</code> RADOS pool。</li><li>暂命名为 <code>auditman</code>，处于开发中，预计随 Ceph U 版本（代号 &quot;Umbrella&quot;）发布。</li></ul></li><li><p><strong>Q&amp;A 环节</strong></p><ul><li>目前为技术预览状态，建议关注上游 PR 或联系开发团队。</li><li>当前优先级是 Tentacle 版本发布，审计日志功能将在之后推进。</li></ul></li></ol><h4 id="后续行动计划" tabindex="-1"><strong>后续行动计划</strong> <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;**后续行动计划**&quot;">​</a></h4><ol><li><p><strong>开发跟踪</strong></p><ul><li>关注 Ceph 上游 PR 和 Umbrella 版本的合并进展。</li></ul></li><li><p><strong>用户建议</strong></p><ul><li>使用终端日志工具记录操作历史。</li></ul></li><li><p><strong>社区协作</strong></p><ul><li>通过邮件列表持续反馈需求，参与测试审计日志功能。</li></ul></li></ol><h4 id="关键词保留-ceph-术语" tabindex="-1"><strong>关键词保留（Ceph 术语</strong>） <a class="header-anchor" href="#关键词保留-ceph-术语" aria-label="Permalink to &quot;**关键词保留（Ceph 术语**）&quot;">​</a></h4><ul><li><strong>核心组件</strong>: CephFS, MDS, RADOS, Perf dump, disaster recovery</li><li><strong>技术概念</strong>: retention policy, backfill, SQLite, structured log, failover</li><li><strong>版本计划</strong>: Umbrella (U release), Tentacle</li></ul><p><strong>会议结束时间</strong>: [未记录具体时间] <strong>参会人员</strong>: Ceph 社区成员、开发团队、存储工程师</p><p><strong>备注</strong>: 本纪要基于 Anthony Dri 代汇报内容整理，部分技术细节需以最终代码实现为准。</p>',11)])])}const u=l(r,[["render",n]]);export{g as __pageData,u as default};
